import { useCallback, useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  locale?: string;
  onChange?: (value: Date | null) => void;
};

const DAY_MS = 24 * 60 * 60 * 1000;

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function shiftDays(days: number): Date {
  return startOfDay(new Date(Date.now() - days * DAY_MS));
}

function isSameDay(a: Date | null, b: Date): boolean {
  return a !== null && startOfDay(a).getTime() === b.getTime();
}

export default function ReportDatePicker({
  defaultValue = null,
  locale = 'ru-RU',
  onChange,
}: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(defaultValue);

  const presets = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', date: shiftDays(0) },
      { id: 'yesterday', label: 'Вчера', date: shiftDays(1) },
      { id: 'week', label: 'Неделя назад', date: shiftDays(7) },
    ],
    [],
  );

  const select = useCallback(
    (next: Date | null) => {
      setValue(next);
      onChange?.(next);
    },
    [onChange],
  );

  return (
    <div style={{ display: 'grid', gap: '12px', maxWidth: '320px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.id}
            active={isSameDay(value, preset.date)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale={locale} value={value} onValueChange={select} />
      <span
        style={{
          color: 'var(--jx-text-2)',
          fontFamily: 'var(--jx-font-sans)',
          fontSize: '13px',
        }}
      >
        {value ? `Дата отчёта: ${value.toLocaleDateString(locale)}` : 'Дата не выбрана'}
      </span>
    </div>
  );
}

